            var parent;
            var pageWidth;
            var pageHeight;
            var offsetTop;
            var offsetLeft;
            var lines;
            var fontSize;
            var lineHeight;
            var itemWidth;
            var itemHeight;
            var xSpace;
            var ySpace;
            var startX;
            var startY;
            var cols;
