            pageHeight = Math.max(parent.scrollHeight, parent.clientHeight);
            offsetTop = parent.offsetTop || 0;
            offsetLeft = parent.offsetLeft || 0;
            lines = settings.watermark_txt.split('\n');
            fontSize = fontSizeToNumber(settings.watermark_fontsize);
            lineHeight = Math.ceil(fontSize * 1.35);
            itemWidth = toNumber(settings.watermark_width, defaults.watermark_width);
