            xSpace = toNumber(settings.watermark_x_space, defaults.watermark_x_space);
            ySpace = toNumber(settings.watermark_y_space, defaults.watermark_y_space);
            startX = toNumber(settings.watermark_x, defaults.watermark_x);
            startY = toNumber(settings.watermark_y, defaults.watermark_y);

