                    item.style.position = 'absolute';
                    item.style.left = x + 'px';
                    item.style.top = y + 'px';
                    item.style.width = itemWidth + 'px';
                    item.style.height = itemHeight + 'px';
                    item.style.zIndex = '9999999';
                    item.style.opacity = settings.watermark_alpha;
                    item.style.fontSize = settings.watermark_fontsize;
                    item.style.fontFamily = settings.watermark_font;
                    item.style.color = settings.watermark_color;
                    item.style.textAlign = 'center';
                    item.style.lineHeight = lineHeight + 'px';
                    item.style.overflow = 'hidden';
                    item.style.pointerEvents = 'none';
                    item.style.userSelect = 'none';
                    item.style.whiteSpace = 'pre-line';
                    item.style.wordBreak = 'break-all';
                    item.style.display = 'flex';
                    item.style.flexDirection = 'column';
                    item.style.alignItems = 'center';
                    item.style.justifyContent = 'center';
                    item.style.webkitTransform = 'rotate(-' + settings.watermark_angle + 'deg)';
                    item.style.MozTransform = 'rotate(-' + settings.watermark_angle + 'deg)';
                    item.style.msTransform = 'rotate(-' + settings.watermark_angle + 'deg)';
